import {
  DataObject,
  restoreIdCounters,
} from '@civ-clone/core-data-object/DataObject';
import { FORMAT, SaveError, SaveGame } from './SaveGame';
import CityName from '@civ-clone/core-civilization/CityName';
import Civilization from '@civ-clone/core-civilization/Civilization';
import { Game, GameSlots } from '@civ-clone/core-game/Game';
import { DISPOSITIONS } from './registries';
import { decode, isBusyRef } from './encode';
import { instance as busyRegistryInstance } from '@civ-clone/core-unit/BusyRegistry';

/**
 * Three tiers, from `03-save-format.md`, and the middle one is the reason they
 * are not one check:
 *
 * - **missing plugin — refuse.** The save names entity types this engine cannot
 *   construct, and loading would fail part-way through with a worse message.
 * - **extra plugin — allow.** New rules apply to the restored game. That is how
 *   a player adds a mod to a running game, and it is a feature.
 * - **version drift — warn.** Blocking on it would make saves worthless after
 *   any dependency update, which across 328 packages is constantly.
 */
export const assertCompatible = (save: SaveGame, game: Game): void => {
  if (save.format !== FORMAT) {
    throw new SaveError(
      `Unsupported save format ${save.format}; this engine reads ${FORMAT}.` +
        (save.format === 1
          ? ' Format 1 saves record an ambiguous class reference for a ' +
            "player's treasury — they load without error and then apply no " +
            'production, food or trade — so they are refused rather than ' +
            'played. See SaveGame.ts.'
          : '')
    );
  }

  const loaded = game.engine.plugins();

  if (Object.keys(loaded).length === 0) {
    throw new SaveError(
      'The engine has no plugin manifest, so compatibility cannot be ' +
        'checked. Loading anyway would mean discovering a missing plugin as a ' +
        'failure part-way through hydration.'
    );
  }

  const missing = Object.keys(save.engine.plugins).filter(
    (name) => !(name in loaded)
  );

  if (missing.length > 0) {
    throw new SaveError(
      `Save needs plugins that are not loaded: ${missing.sort().join(', ')}.`
    );
  }

  const drifted = Object.entries(save.engine.plugins)
    .filter(([name, version]) => loaded[name] !== version)
    .map(([name, version]) => `${name} ${version} → ${loaded[name]}`);

  if (drifted.length > 0) {
    game.engine.emit('save:version-drift', drifted);
  }
};

/**
 * Load a save into a game.
 *
 * Seven passes, and only the first two touch entity data. **Allocate-then-fill
 * removes the topological ordering requirement entirely**: references resolve
 * against a complete map, so cycles cost nothing and a plugin adding one field
 * cannot break loading with a confusing error. Entities are still *written* in
 * id order, for diffability rather than because the loader needs it.
 */
export const hydrate = (save: SaveGame, game: Game): void => {
  assertCompatible(save, game);

  // Before anything is allocated, or the first entity created after the load
  // takes an id a loaded entity already holds.
  // The turn, before anything can read it. It is recorded in the file's
  // metadata rather than as an entity — nothing references a `Turn` — so
  // without this a loaded game resumes at turn 0 with a turn-40 world. In one
  // process that went unnoticed: the loaded game adopted the same `Turn`
  // object the saved one had been counting. The year follows from the turn.
  game.turn.set(save.meta.turn);

  restoreIdCounters(save.idCounters);
  game.rng.restore(save.rng.seed, save.rng.calls);

  const instances = new Map<string, DataObject>();

  // Pass 1 — allocate. No constructors, so no `city:created`, no `unit:created`
  // and no ordering requirement. This is what the `#private` → `private`
  // migration bought.
  save.entities.forEach(({ id, type }) => {
    const Type = game.classes.get(type);

    if (!Type) {
      throw new SaveError(
        `Unknown entity type '${type}'. Either a plugin is missing, or the ` +
          'class was never registered with `game.classes`.'
      );
    }

    instances.set(id, Object.create(Type.prototype) as DataObject);
  });

  // Pass 2 — fill. `$ref`s resolve against the complete map above.
  const context = { instances, classes: game.classes };

  save.entities.forEach(({ id, keys, state }) => {
    const entity = instances.get(id)!;

    Object.assign(entity, decode(state, context), {
      _id: id,
      _keys: [...keys],
    });
  });

  // Pass 3 — re-attach the collaborators and caches a file cannot carry, and
  // run any `onHydrated` hook. `inject` throws if it leaves a transient field
  // undefined, so a class this does not know about fails the load rather than
  // returning `undefined` from an accessor.
  // All of them together: a hook may read any other entity — `City` recomputes
  // its fat cross from the world — so filling, hooks and the transient-field
  // assertion are three sweeps rather than one pass per entity.
  game.injectAll(instances.values());

  // Pass 4 — registry membership, in saved order. `EntityRegistry.register`
  // dedupes by identity, so a definition registry that plugin imports already
  // filled does not double up.
  Object.entries(save.registries).forEach(([slot, ids]) => {
    if (DISPOSITIONS[slot as keyof GameSlots] !== 'state') {
      throw new SaveError(
        `Save carries membership for '${slot}', which is not runtime state ` +
          'in this engine. Loading it would register duplicates over the ' +
          'definitions plugin imports have already created.'
      );
    }

    const registry = (game as unknown as Record<string, unknown>)[slot] as {
      register(...entries: DataObject[]): void;
    };

    registry.register(
      ...ids.map((id) => {
        const entity = instances.get(id);

        if (!entity) {
          throw new SaveError(
            `Registry '${slot}' names entity '${id}', which the save does ` +
              'not contain.'
          );
        }

        return entity;
      })
    );
  });

  // Pass 5 — rebuild the rules a unit was holding.
  //
  // Separate from the fill because rebuilding one needs the entity that holds
  // it: `decode` walks a field's value with no idea whose field it is, so it
  // leaves the marker alone and this resolves it with the owner in hand.
  //
  // The rule itself is not restored — it is *rebuilt*, by the package that
  // owns it, from the entity and whatever `PendingEffect` says about it. **And
  // that is why it runs here, after registry membership rather than before
  // it.** A delayed action's factory asks `pendingEffects.getByTarget(unit)`
  // for the effect carrying its completion turn, and a registry nothing has
  // been registered into yet answers with nothing: a unit saved part-way
  // through fortifying failed to load, naming an effect the file did in fact
  // contain. Filling the objects is not enough; they have to be *findable*.
  //
  // Findable *in this game*. The factories are registered at import, closing
  // over the singleton registries, so the game is passed along: loaded into
  // any `Game` but `defaultGame` — `gameForLoad`'s, say — a fortifying unit's
  // factory searched the singletons, found only the saved game's effect, owed
  // to the saved unit rather than this one, and refused the load
  // (civ-clone/web-renderer#245).
  instances.forEach((entity) => {
    const record = entity as unknown as Record<string, unknown>;

    Object.keys(record).forEach((field) => {
      const value = record[field];

      if (isBusyRef(value)) {
        record[field] = busyRegistryInstance.rebuild(
          value.$busy,
          entity as never,
          game
        );
      }
    });
  });

  // Pass 6 — re-apply the claims players hold on constructor registries.
  reclaim(save, game, instances);

  // Pass 7 — take the names already handed out back out of the name pool.
  reclaimCityNames(save, game, instances);

  game.engine.emit('save:loaded', save.meta);
};

/**
 * `civ1-player` unregisters a civilisation when a player takes it, so no two
 * players share one. A fresh boot re-registers all of them, so a loaded game
 * would let a later player claim one that is already in use.
 *
 * No extra save data: the restored players already carry their civilisations
 * and leaders, so the claims can be replayed from them.
 */
const reclaim = (
  save: SaveGame,
  game: Game,
  instances: Map<string, DataObject>
): void => {
  // The players still in the game, and those who were, whose civilizations stay claimed: a defeated player is gone
  //  from `players` but keeps its `PlayerWorld`. Without them a load hands a destroyed civilization out again
  //  (civ-clone/web-renderer#178).
  const players = [
    ...new Set(
      [
        ...(save.registries.players ?? []).map((id) => instances.get(id)),
        ...(save.registries.playerWorlds ?? []).map((id) =>
          (
            instances.get(id) as unknown as
              | { player?: () => DataObject }
              | undefined
          )?.player?.()
        ),
      ].filter((entity): entity is DataObject => entity !== undefined)
    ),
  ];

  players.forEach((player) => {
    const civilization = (
      player as unknown as {
        civilization?: () => { sourceClass<T>(): T; leader?: () => unknown };
      }
    ).civilization?.();

    if (!civilization) {
      return;
    }

    const CivilizationType = civilization.sourceClass<never>();

    if (game.civilizations.includes(CivilizationType)) {
      game.civilizations.unregister(CivilizationType);
    }

    const leader = (
      civilization as { leader?: () => { sourceClass<T>(): T } | null }
    ).leader?.();

    if (leader) {
      const LeaderType = leader.sourceClass<never>();

      if (game.leaders.includes(LeaderType)) {
        game.leaders.unregister(LeaderType);
      }
    }
  });
};

/**
 * The city name pool is a definition registry, so a fresh boot fills it again
 * and a loaded game would hand out names the saved game already used — the
 * capital's first, because founding a city always asks for a capital name
 * (civ-clone/web-renderer#120).
 *
 * A file that records `cityNames` is replayed exactly, which also leaves the
 * pool as the saved game had it, so the names drawn after a load are the ones
 * an uninterrupted game would have drawn. An older file has only its cities to
 * go on: their names come out of the pool, each against the civilization of
 * the player who founded it, and the counter resumes after the highest `City #n`. The
 * names of cities destroyed before such a save can't be recovered.
 */
const reclaimCityNames = (
  save: SaveGame,
  game: Game,
  instances: Map<string, DataObject>
): void => {
  if (save.cityNames) {
    game.cityNames.restore(
      save.cityNames.taken.map(({ name, civilization }) => {
        if (civilization === null) {
          return new CityName(name, null);
        }

        const CivilizationType = game.classes.get(civilization);

        if (!CivilizationType) {
          throw new SaveError(
            `City name '${name}' belongs to civilization '${civilization}', ` +
              'which is not registered with `game.classes`.'
          );
        }

        return new CityName(
          name,
          CivilizationType as unknown as typeof Civilization
        );
      }),
      save.cityNames.counter
    );

    return;
  }

  type Owner = { civilization(): { sourceClass<T>(): T } };

  const cities = (save.registries.cities ?? [])
    .map((id) => instances.get(id))
    .filter((entity): entity is DataObject => entity !== undefined)
    .map(
      (city) =>
        city as unknown as {
          name(): string;
          player(): Owner;
          originalPlayer?(): Owner;
        }
    );

  const counter = cities.reduce((highest, city) => {
    const [, number] = city.name().match(/^City #(\d+)$/) ?? [];

    return number ? Math.max(highest, Number(number) + 1) : highest;
  }, 1);

  // Against the civilization that founded the city, not the one holding it:
  // a Greek Athens captured by England took its name from the Greek pool.
  game.cityNames.restore(
    cities.map(
      (city) =>
        new CityName(
          city.name(),
          (city.originalPlayer?.() ?? city.player())
            .civilization()
            .sourceClass<typeof Civilization>()
        )
    ),
    counter
  );
};

export default hydrate;
