export interface IEffect {
  apply(...args: any[]): any;
}

export class Effect<T extends any[] = any[], R = any> implements IEffect {
  private _effect: (...args: T) => R;

  constructor(effect: (...args: T) => R) {
    this._effect = effect;
  }

  apply(...args: T): R {
    return this._effect(...args);
  }
}

export default Effect;
