import {
  EntityRegistry,
  IEntityRegistry,
} from '@civ-clone/core-registry/EntityRegistry';
import { IDataObject } from '@civ-clone/core-data-object/DataObject';
import PendingEffect from './PendingEffect';

/**
 * What to do when an effect comes due. Registered at import, never saved.
 *
 * `context` is whatever the discharger has in hand that the effect could not
 * carry. A delayed action passes the action it performed, so completion uses
 * the registries that action was constructed with rather than the singletons a
 * handler registered at import would otherwise reach for. A handler must not
 * *need* it: an effect discharged after a load has only what the save held.
 */
export type PendingEffectHandler = (
  effect: PendingEffect,
  ...context: unknown[]
) => void;

export class UnknownHandlerError extends Error {}

export interface IPendingEffectRegistry extends IEntityRegistry<PendingEffect> {
  discharge(effect: PendingEffect, ...context: unknown[]): void;
  getByHandler(handler: string): PendingEffect[];
  getByTarget(target: IDataObject): PendingEffect[];
  handler(handler: string, apply: PendingEffectHandler): void;
  handlers(): string[];
}

/**
 * The effects the game owes, and what to do about each.
 *
 * Two halves that are saved differently on purpose: the **effects** are
 * entities and go in the save; the **handlers** are functions and never do.
 * A handler is looked up by the identifier its effect carries, so the closure
 * stays in the plugin that registered it and the file holds only a name.
 *
 * Nothing here decides *when* an effect is due — see `PendingEffect`. A package
 * registers an ordinary rule that watches whatever it cares about, asks for the
 * effects targeting it, and discharges the ones that have come due.
 */
export class PendingEffectRegistry
  extends EntityRegistry<PendingEffect>
  implements IPendingEffectRegistry
{
  private _handlers: Map<string, PendingEffectHandler> = new Map();

  constructor() {
    super(PendingEffect);
  }

  /**
   * Register what to do when effects with this identifier come due.
   *
   * Last registration wins, so a variant can override a base ruleset's
   * behaviour by registering the same identifier afterwards — the same
   * override story `RuleRegistry.replace` gives named rules.
   */
  handler(handler: string, apply: PendingEffectHandler): void {
    this._handlers.set(handler, apply);
  }

  handlers(): string[] {
    return [...this._handlers.keys()].sort();
  }

  getByHandler(handler: string): PendingEffect[] {
    return this.filter(
      (effect: PendingEffect): boolean => effect.handler() === handler
    );
  }

  getByTarget(target: IDataObject): PendingEffect[] {
    return this.filter(
      (effect: PendingEffect): boolean => effect.target() === target
    );
  }

  /**
   * Apply an effect and forget it.
   *
   * Unregistered *before* the handler runs, and the order matters: a handler
   * that registers a fresh effect — Darwin's Voyage owing a second completion
   * — must not have it removed by the discharge that triggered it. It also
   * means a handler that throws does not leave the effect to be retried
   * forever, which is the failure mode of a queue that removes on success.
   *
   * An unknown handler throws rather than silently dropping the effect. A save
   * loaded without the plugin that owns a debt should say so: the alternative
   * is a unit that never finishes its road and nothing to explain why.
   */
  discharge(effect: PendingEffect, ...context: unknown[]): void {
    const apply = this._handlers.get(effect.handler());

    if (!apply) {
      throw new UnknownHandlerError(
        `No handler is registered for '${effect.handler()}', so the effect it ` +
          'records cannot be applied. The package that owns it is probably ' +
          'not loaded. Known: ' +
          (this.handlers().join(', ') || '(none)')
      );
    }

    this.unregister(effect);

    apply(effect, ...context);
  }
}

export const instance: PendingEffectRegistry = new PendingEffectRegistry();

export default PendingEffectRegistry;
