// Explores with one unit for one turn, as a standing order from its player (civ-clone/web-renderer#198), using the
//  game's `Explore` strategy (`base-strategy-explore`). The order lives in a `StrategyNote`, so it is saved with the
//  game, and the unit carries the `Exploring` busy rule while the order stands.
import {
  StrategyNote,
  generateKey as generateRawKey,
} from '@civ-clone/core-strategy/StrategyNote';
import Criterion from '@civ-clone/core-rule/Criterion';
import Dependencies from '@civ-clone/base-strategy-ai/lib/Dependencies';
import Effect from '@civ-clone/core-rule/Effect';
import ExploreStrategy from '@civ-clone/base-strategy-explore/Strategies/Unit/Explore';
import Exploring from '../Busy/Exploring';
import Memory from '@civ-clone/base-strategy-ai/lib/Memory';
import Path from '@civ-clone/core-world-path/Path';
import Player from '@civ-clone/core-player/Player';
import StrategyRegistry from '@civ-clone/core-strategy/StrategyRegistry';
import Tile from '@civ-clone/core-world/Tile';
import Unit from '@civ-clone/core-unit/Unit';
import UnitOrder from '@civ-clone/base-strategy-ai/PlayerActions/UnitOrder';
import enemyAdjacent from '@civ-clone/base-strategy-ai/lib/Unit/enemyAdjacent';
import { findStrategy } from '@civ-clone/base-strategy-ai/Strategies/lib/OrderStrategy';

export const generateKey = (unit: Unit): string =>
  generateRawKey(unit, 'explore');

// What a save keeps of the order: the player who gave it, and where the unit is heading, if anywhere. Plain values and
//  entities only, never a `Path`, which a save restores as a plain array (see `base-unit-action-goto`).
export interface ExploreNote {
  player: Player;
  target: Tile | null;
}

// The `Exploring` rule, built the same way fresh or restored. It never ends by itself: the order ends when the
//  strategy hands the unit back, or when the player gives the unit other orders.
export const exploring = (): Exploring =>
  new Exploring(
    new Criterion((): boolean => false),
    new Effect((): void => {})
  );

const forget = (unit: Unit, dependencies: Dependencies, player: Player) => {
  const note = dependencies.strategyNoteRegistry.getByKey(generateKey(unit));

  if (note) {
    dependencies.strategyNoteRegistry.unregister(note);
  }

  dependencies.memoryRegistry.memoryFor(player).unitPathData.delete(unit);
};

// Ends the order and gives the unit back to its player, with whatever moves it has left.
export const handBack = (unit: Unit, dependencies: Dependencies): void => {
  forget(unit, dependencies, unit.player());

  if (unit.destroyed()) {
    return;
  }

  unit.setBusy();
  unit.setActive();
};

// After a load the strategy's memory is empty: the unit carries on to where the note says it was heading, as
//  `surveyTargets` takes up a saved survey rather than surveying again.
const resume = (
  unit: Unit,
  dependencies: Dependencies,
  memory: Memory,
  target: Tile | null
): void => {
  if (!target || target === unit.tile() || memory.unitPathData.has(unit)) {
    return;
  }

  const path = Path.for(
    unit,
    unit.tile(),
    target,
    dependencies.pathFinderRegistry
  );

  if (path) {
    memory.unitPathData.set(unit, path);
  }
};

// Runs the order for `unit`'s turn, with the moves it has. Returns whether the order still stands. Synchronous, as a
//  `TurnStart` rule has to be.
export const exploreUnit = (
  unit: Unit,
  strategyRegistry: StrategyRegistry,
  dependencies: Dependencies
): boolean => {
  const note = dependencies.strategyNoteRegistry.getByKey<ExploreNote>(
    generateKey(unit)
  );

  if (!note) {
    return false;
  }

  const order = note.value(),
    player = unit.player();

  // The unit was lost, changed hands or was given other orders (selecting a busy unit clears its busy rule): the
  //  order is over, and the unit is left as it is.
  if (
    unit.destroyed() ||
    order.player !== player ||
    !(unit.busy() instanceof Exploring)
  ) {
    forget(unit, dependencies, order.player);

    return false;
  }

  const strategy = findStrategy(strategyRegistry, ExploreStrategy);

  if (!strategy || enemyAdjacent(dependencies, player, unit)) {
    handBack(unit, dependencies);

    return false;
  }

  const memory = dependencies.memoryRegistry.memoryFor(player);

  resume(unit, dependencies, memory, order.target);

  // A busy unit isn't made active at the start of its turn, and the strategy only moves an active one.
  unit.setActive();

  const carryOn = strategy.order(new UnitOrder(player, unit));

  if (unit.destroyed()) {
    forget(unit, dependencies, player);

    return false;
  }

  // A move changed what the unit is doing (it went aboard a ship, say): the order is over.
  if (!(unit.busy() instanceof Exploring)) {
    forget(unit, dependencies, player);

    return false;
  }

  if (!carryOn) {
    handBack(unit, dependencies);

    return false;
  }

  order.target = memory.unitPathData.get(unit)?.end() ?? null;

  unit.setActive(false);

  return true;
};

// Starts the order for `unit`, replacing any it had.
export const startExploring = (
  unit: Unit,
  dependencies: Dependencies
): void => {
  unit.setBusy(exploring());

  dependencies.memoryRegistry
    .memoryFor(unit.player())
    .unitPathData.delete(unit);
  dependencies.strategyNoteRegistry.replace(
    new StrategyNote<ExploreNote>(generateKey(unit), {
      player: unit.player(),
      target: null,
    })
  );
};

export default exploreUnit;
