import { instance as classRegistryInstance } from '@civ-clone/core-data-object/ClassRegistry';
import Yield from '@civ-clone/core-yield/Yield';

/**
 * Tagged `GoldYield`, because three packages declare a class called `Gold`:
 * this yield, `base-terrain-feature-gold`'s terrain feature and
 * `base-goody-hut-gold`'s action. A save records a class by *name*, and only
 * one class can own a name — `PlayerTreasury._yield` was written as
 * `{ $class: 'Gold' }` and read back as the terrain feature. Nothing failed
 * at load: `getByPlayerAndType` found no treasury, threw inside
 * `ProcessYield`, and a loaded game applied no production, no food and no
 * trade with nothing to say why.
 *
 * The terrain feature keeps the bare name, because it is a saved entity and
 * its `type` and ids appear in files already written.
 */
export class Gold extends Yield {
  static readonly type: string = 'GoldYield';
}

// Registered here because nothing else would: `registerClasses` names the
// `core-` entity classes explicitly and finds the rest through the
// `ConstructorRegistry`s, and a city yield is in neither — it is constructed
// directly. Without this the reference above resolves to nothing on load.
classRegistryInstance.register(Gold);

export default Gold;
