import Rule from '@civ-clone/core-rule/Rule';
import Unit from '@civ-clone/core-unit/Unit';

export interface IStrength {
  attack: number;
  defence: number;
}

// What a unit adds to its player's military strength, as attack and defence. The matches are added together
//  (`strength`), and a unit no rule matches adds nothing, so a ruleset can leave a kind of unit out.
export class MilitaryStrength extends Rule<[Unit], IStrength> {}

export default MilitaryStrength;
