import Dependencies, {
  createDependencies,
} from '@civ-clone/base-strategy-ai/lib/Dependencies';
import {
  RuleRegistry,
  instance as ruleRegistryInstance,
} from '@civ-clone/core-rule/RuleRegistry';
import {
  StrategyNoteRegistry,
  instance as strategyNoteRegistryInstance,
} from '@civ-clone/core-strategy/StrategyNoteRegistry';
import {
  StrategyRegistry,
  instance as strategyRegistryInstance,
} from '@civ-clone/core-strategy/StrategyRegistry';
import exploreUnit, { exploring, startExploring } from './lib/exploreUnit';
import Action from '@civ-clone/core-unit/Action';
import Exploring from './Busy/Exploring';
import Moved from '@civ-clone/core-unit/Rules/Moved';
import Tile from '@civ-clone/core-world/Tile';
import Unit from '@civ-clone/core-unit/Unit';
import { instance as busyRegistryInstance } from '@civ-clone/core-unit/BusyRegistry';

export type { ExploreNote } from './lib/exploreUnit';
export { exploring, generateKey, handBack } from './lib/exploreUnit';

// Explore: a standing order for one of a player's units to explore by itself, turn after turn, using the game's
//  `Explore` strategy (civ-clone/web-renderer#198). It never attacks or negotiates, and hands the unit back to its
//  player when there's nothing left to explore that it can reach, another player's unit is near, or the game has no
//  `Explore` strategy at all.
export class Explore extends Action {
  private _dependencies: Dependencies;
  private _strategyRegistry: StrategyRegistry;

  // `dependencies` are the registries the strategy's helpers read, the game's own (`dependenciesFor(game)`); any left
  //  out are the module singletons.
  constructor(
    from: Tile,
    to: Tile,
    unit: Unit,
    ruleRegistry: RuleRegistry = ruleRegistryInstance,
    strategyRegistry: StrategyRegistry = strategyRegistryInstance,
    strategyNoteRegistry: StrategyNoteRegistry = strategyNoteRegistryInstance,
    dependencies: Partial<Dependencies> = {}
  ) {
    super(from, to, unit, ruleRegistry);

    this._strategyRegistry = strategyRegistry;
    this._dependencies = createDependencies({
      ruleRegistry,
      strategyNoteRegistry,
      ...dependencies,
    });
  }

  // Starts the order and explores straight away with the moves the unit has left.
  perform(): void {
    const unit = this.unit();

    startExploring(unit, this._dependencies);
    exploreUnit(unit, this._strategyRegistry, this._dependencies);

    if (!unit.destroyed()) {
      this.ruleRegistry().process(Moved, unit, this);
    }
  }
}

// Without this a unit saved while exploring fails to load. Nothing in the rule depends on the unit: what the order
//  needs is in its note, which is saved.
busyRegistryInstance.register(Exploring, (): Exploring => exploring());

export default Explore;
